"""Common audio clock, true whole-song arrays, two independently labeled timelines."""
import base64,json
from .common import *
from dunhuang.research.strong_baseline_r52.view import finish,encode

def viewer(out,pop,arrays,result):
 folder=fresh(out/'viewer');cases=[]
 for song in sorted({r['song'] for r in result['records']}):
  records=[r for r in result['records'] if r['song']==song and r['status']=='NUMERICAL_WHOLE_SONG_RESEARCH_PREVIEW'];methods=[]
  for r in records:
   P=arrays[f'song{song}_{r["arm"]}_P'];jerk=np.r_[np.zeros(3),np.sqrt(np.mean((np.diff(P.astype(float),n=3,axis=0)*27000)**2,axis=(1,2)))];methods.append(dict(name=r['arm']+' · '+dict(B0='冻结固定槽位',B1='结构槽位',B2='置乱结构槽位',B3='结构槽位＋主题规划',C1='固定结构槽位＋执行档案',C2='来源感知联合时长',C3='共同图＋置乱边界奖励')[r['arm']],data=encode(P),jerk=jerk.tolist()))
  if not methods:continue
  frame=result['music'][str(song)]['frames'];audio='data:audio/wav;base64,'+base64.b64encode(Path(pop.tracks[song]['path']).read_bytes()).decode();meta=dict(scope='R58完整音乐几何对照；音频结构为自动代理，非真实乐句标注；世界Root／接触未知，Native24不可评。',regions=[],plans=records,music_diagnostics={n:arrays[f'music{song}_{n}'].tolist() for n in ('proposal','held_boundary','proxy_boundaries')},phrase_truth='NOT_EVALUABLE',human_reviewed=False);cases.append(dict(label='dunhuangwu'+str(song+2)+' · 整曲',frames=frame,origin=0,audio=audio,methods=methods,meta=meta))
 finish(folder,cases,pop.net.parents);path=folder/'index.html';page=path.read_text(encoding='utf8').replace('R52','R58').replace('保留 Heuristic 强基线；生成比较同一完整来源与几何基线，修复评价时间坐标。来源阶段为观测运动学代理，世界 Root／接触及 Native24 尚未取得完整资格。','同一首完整音乐；C2联合选择来源与有限时间边界。原G0/G1筛查与R57异常恢复不变。边界是自动代理，世界Root／接触未知，Native24不可评。')
 page=page.replace('<section id="panels">','<p><label>3D观察方位 <input id="yaw" type="range" min="-180" max="180" value="-20"></label></p><p>音频结构：绿色为谱变化提案，紫色为另一路自动边界代理；两者都不是人工乐句真值。点击曲线可跳转。</p><canvas id="structure" width="1100" height="130" style="width:100%;background:white"></canvas><section id="timelines"></section><section id="panels">').replace("160+110*(.85*p[k]-.5*p[k+2])","160+110*(Math.cos(Number(document.getElementById('yaw').value)*Math.PI/180)*p[k]+Math.sin(Number(document.getElementById('yaw').value)*Math.PI/180)*p[k+2])")
 page=page.replace('</style>','#timelines{display:grid;gap:10px;margin:12px 0} .strip{display:flex;height:22px;cursor:pointer}.seg{min-width:1px}.core{background:#79af97}.transition{background:#d2b679}.current{outline:3px solid #8a3d2c} .line-label{font-weight:bold;padding:4px}</style>')
 extra=r"""const baseShow=show;show=function(t){baseShow(t);const c=document.getElementById('structure'),g=c.getContext('2d');g.clearRect(0,0,1100,130);['proposal','held_boundary'].forEach((name,i)=>{g.strokeStyle=i?'#a46bb7':'#218873';g.beginPath();row.meta.music_diagnostics[name].forEach((v,k)=>{const x=k/(row.frames-1)*1100,y=120-v*105;k?g.lineTo(x,y):g.moveTo(x,y)});g.stroke()});g.fillStyle='#a46bb7';row.meta.music_diagnostics.proxy_boundaries.forEach(k=>g.fillRect(k/(row.frames-1)*1100,0,1,12));g.fillStyle='#8a3d2c';g.fillRect(frame/(row.frames-1)*1100,15,2,110);const host=document.getElementById('timelines');host.replaceChildren();row.meta.plans.forEach(plan=>{const wrap=document.createElement('div'),text=document.createElement('div'),strip=document.createElement('div');text.className='line-label';const region=plan.regions.find(r=>r.interval[0]<=frame&&frame<r.interval[1]);let event=plan.events.find(e=>e.target_interval[0]<=frame&&frame<e.target_interval[1]);text.textContent=plan.arm+' · '+(region?.kind==='core'?(event?.source_uid??'来源动作'):'几何过渡')+' · Core '+plan.events.map(e=>(e.target_interval[1]-e.target_interval[0])).join('/');strip.className='strip';plan.regions.forEach(r=>{let seg=document.createElement('div');seg.className='seg '+r.kind+(r===region?' current':'');seg.style.width=((r.interval[1]-r.interval[0])/row.frames*100)+'%';seg.title=plan.arm+' '+r.kind+' ['+r.interval.join(',')+')';seg.onclick=()=>{running=false;audio.pause();audio.currentTime=r.interval[0]/30;show(r.interval[0])};strip.append(seg)});wrap.append(text,strip);host.append(wrap)})};document.getElementById('structure').onclick=e=>{const b=e.currentTarget.getBoundingClientRect(),f=Math.round((e.clientX-b.left)/b.width*(row.frames-1));running=false;audio.pause();audio.currentTime=f/30;show(f)};document.getElementById('yaw').oninput=()=>show(frame);show(frame);"""
 page=page.replace('</script></html>',extra+'</script></html>');path.write_text(page,encoding='utf8');write(folder/'protocol.json',dict(cases=len(cases),audio_embedded=True,source='SAVED_TRUE_GEOMETRY_ARRAYS_NOT_DIFFUSION',files=[dict(name=p.name,bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(folder.iterdir()) if p.name!='protocol.json']))
